const body = $input.first().json.body || $input.first().json;
const hero = String(body.heroImage || '').replace(/'/g, "''");
const heroMy = String(body.heroImage_my || '').replace(/'/g, "''");
const svcTradein = String(body.svcTradeinIcon || '').replace(/'/g, "''");
const svcTestride = String(body.svcTestrideIcon || '').replace(/'/g, "''");
const benefits = JSON.stringify(body.benefits || []).replace(/'/g, "''");
const catOv = JSON.stringify(body.categoryOverrides || {}).replace(/'/g, "''");
const faq = JSON.stringify(body.faq || []).replace(/'/g, "''");
const faqMy = JSON.stringify(body.faq_my || []).replace(/'/g, "''");
const sql = `INSERT INTO site_config (id, hero_image, hero_image_my, svc_tradein_icon, svc_testride_icon, benefits, category_overrides, faq, faq_my, updated_at)
VALUES (1, '${hero}', '${heroMy}', '${svcTradein}', '${svcTestride}', '${benefits}'::jsonb, '${catOv}'::jsonb, '${faq}'::jsonb, '${faqMy}'::jsonb, NOW())
ON CONFLICT (id) DO UPDATE SET
  hero_image = EXCLUDED.hero_image,
  hero_image_my = EXCLUDED.hero_image_my,
  svc_tradein_icon = EXCLUDED.svc_tradein_icon,
  svc_testride_icon = EXCLUDED.svc_testride_icon,
  benefits = EXCLUDED.benefits,
  category_overrides = EXCLUDED.category_overrides,
  faq = EXCLUDED.faq,
  faq_my = EXCLUDED.faq_my,
  updated_at = NOW();`;
return [{ json: { sql } }];
